code='''def transform(grid):
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]
    row_seps = [r for r in range(h) if len(set(g[r])) == 1 and g[r][0] != bg]
    col_seps = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1 and g[0][c] != bg]
    def segments(n, seps):
        out=[]; start=0
        for x in seps:
            if start < x: out.append((start,x))
            start=x+1
        if start<n: out.append((start,n))
        return out
    rs, cs = segments(h,row_seps), segments(w,col_seps)
    # The non-empty compartment is the source; copy it into every blank compartment.
    best = None; best_count = -1
    for ri,(r0,r1) in enumerate(rs):
        for ci,(c0,c1) in enumerate(cs):
            count=sum(g[r][c] != bg for r in range(r0,r1) for c in range(c0,c1))
            if count > best_count:
                best_count=count; best=(ri,ci)
    if best is None or best_count <= 0: return g
    sri,sci=best; sr0,sr1=rs[sri]; sc0,sc1=cs[sci]
    for ri,(r0,r1) in enumerate(rs):
        for ci,(c0,c1) in enumerate(cs):
            if (ri,ci)==best or (r1-r0)!=(sr1-sr0) or (c1-c0)!=(sc1-sc0):
                continue
            for dr in range(sr1-sr0):
                for dc in range(sc1-sc0):
                    g[r0+dr][c0+dc]=g[sr0+dr][sc0+dc]
    return g
'''
